import re, sys
lines = open(sys.argv[1]).read().splitlines()
cols = lines[0].split() if lines else []
wide = "PATH" not in cols
rows = lines[1:]
vic = [l.split() for l in open(sys.argv[2]).read().splitlines()]
want = set(open(sys.argv[3]).read().split()) if sys.argv[4] == "all" else set()
by = {p: l for l, p in vic}
seen = set(); out = {l: [] for l, _ in vic}
for r in rows:
    f = r.split(None, 8 if wide else 5)
    if len(f) < (9 if wide else 6):
        continue
    seen.add(f[1])
    if f[1] in by:
        m = re.match(r"^(\d+)", f[3])
        if m:
            name = f[8] if wide else f[5]
            out[by[f[1]]].append((int(m.group(1)), name if name.startswith("/") else "anonymous"))
if sys.argv[4] == "all":
    print("all-visible-pids-listed=" + ("yes" if want <= seen else "no:" + ",".join(sorted(want - seen))))
for l, _ in vic:
    print("%s descriptors=%s" % (l, sorted(out[l])))

